package com.rappistream.dashboardaggregator.infrastructure.history;  import com.rappistream.dashboardaggregator.domain.OrderEvent; import com.rappistream.dashboardaggregator.ports.OrderHistoryPort;  import org.springframework.stereotype.Component;  @Component public class JpaOrderHistoryAdapter implements OrderHistoryPort {      private final OrderHistoryJpaRepository repository;      public JpaOrderHistoryAdapter(OrderHistoryJpaRepository repository) {         this.repository = repository;     }      @Override     public void record(OrderEvent event) {         OrderHistoryJpaEntity entity = new OrderHistoryJpaEntity();         entity.setOrderId(event.orderId());         entity.setEventType(event.eventType().name());         entity.setDriverId(event.driverId());         entity.setOccurredAt(event.occurredAt());         repository.save(entity);     } }
